args.sparql:
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  {
    VALUES ?film { dbr:Final_Destination_3 }
  } UNION {
    ?film rdfs:label ?filmLabel .
    FILTER(langMatches(lang(?filmLabel), "EN"))
    FILTER(regex(str(?filmLabel), "Wuthering Heights", "i") && regex(str(?filmLabel), "Emily", "i"))
    ?film a dbo:Film .
  }
  OPTIONAL { ?film dbo:director ?director . }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
  OPTIONAL { ?director dbo:birthDate ?dob1 . }
  OPTIONAL { ?director dbp:birth_date ?dob2 . }
  BIND(COALESCE(?dob1, ?dob2) AS ?birthDate)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "EN")) }
}
ORDER BY ?birthDate
LIMIT 2

